mapper.select:
SELECT a.id, a.project_id 'project.id', a.monomer_id 'monomer.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', a.create_time, a.process_id, mbp.`name` process_name, a.audit_time, a.user_id, u1.`name` user_name, a.audit_user_id, audit.`name` audit_user_name, a.audit_status FROM mes_building_wages_change_audit a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN mes_building_process mbp ON a.process_id=mbp.id LEFT JOIN sys_user u1 ON u1.id=a.user_id LEFT JOIN sys_user audit ON audit.id=a.audit_user_id
a.organization_type=#{organizationType}
and a.project_id=#{projectId}
and a.monomer_id=#{monomerId}
and a.process_id=#{processId}
and a.audit_status=#{status}
